const DOOM_LINE_SIGNATURE=['断命の予告線',28,8,'前方520・半幅18の直線上から、HP35%超の敵を近い順に最大5体選び、5秒の印を付ける。期限より前に生きたまま発動時最大HPの35%以下になると300%の追撃（各1回）。この技は最初には攻撃しない。最初から瀕死の敵・訓練標的・後から線に入る敵は対象外。壁越しに印は付かず、対象が自分から600超・壁に隠れる・倒れる・消えるとその印を失う。死亡・地域移動・再発動で全解除。範囲補正は最初の線幅のみ。','M6 26H48M13 9V43M26 9V43M39 9V43M9 17L17 9M22 17L30 9M35 17L43 9M10 38H16M23 38H29M36 38H42'];
SIGNATURE_SKILLS.push(DOOM_LINE_SIGNATURE);Object.assign(GEM.crafted_8_5,{name:DOOM_LINE_SIGNATURE[0],cost:28,cool:8,desc:DOOM_LINE_SIGNATURE[3],ability:null,signature:117,tags:['spell','area']});
SIGNATURE_AUDIO.push(['doomline',210,.3]);SKILL_AUDIO_FAMILIES.heavy.add('doomline');
function doomLineValid(s){return !s.finished&&s.owner===p&&s.world===dungeon&&!dead&&p?.hp>0;}
function doomLineEntryValid(v){return !v.done&&v.e.hp>0&&enemies.includes(v.e)&&dist(p,v.e)<=600&&lineClear(p,v.e);}
function doomLineCandidates(s){const dx=Math.cos(s.angle),dy=Math.sin(s.angle);return enemies.map(e=>({e,along:(e.x-s.origin.x)*dx+(e.y-s.origin.y)*dy,side:Math.abs((e.x-s.origin.x)*dy-(e.y-s.origin.y)*dx)})).filter(v=>!v.e.dummy&&Number.isFinite(v.e.max)&&v.e.max>0&&v.e.hp>v.e.max*.35&&v.along>=0&&v.along<=520&&v.side<=18*s.build.radius&&lineClear(s.origin,v.e)).sort((a,b)=>a.along-b.along).slice(0,5).map(({e})=>({e,threshold:e.max*.35,done:false,impact:null}));}
const doomLineCastBase=castCraftedSkill;
castCraftedSkill=(build,...args)=>{const result=doomLineCastBase(build,...args);if(GEM[build.type]?.signature!==117)return result;const s=signatureSpells.at(-1);if(s?.mode!==117)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==117||v===s);Object.assign(s,{owner:p,world:dungeon,finished:false,target:null,entries:doomLineCandidates(s)});s.length=0;for(let d=4;d<=520;d+=4){if(!lineClear(s.origin,{x:s.origin.x+Math.cos(s.angle)*d,y:s.origin.y+Math.sin(s.angle)*d}))break;s.length=d;}if(!s.entries.length){s.finished=true;signatureSpells=signatureSpells.filter(v=>v!==s);say('直線上のHP35%超の敵を狙ってください');}return result;};
const doomLineStepBase=stepSignature;
stepSignature=(s,dt)=>{if(s.mode!==117)return doomLineStepBase(s,dt);if(!doomLineValid(s)){s.finished=true;return false;}if(paused||!Number.isFinite(dt)||dt<=0)return true;s.time+=dt;
 for(const v of s.entries){if(v.done)continue;if(s.time>=5-1e-8||!doomLineEntryValid(v)){v.done=true;continue;}if(v.e.hp<=v.threshold){v.done=true;v.impact={x:v.e.x,y:v.e.y,time:s.time};spellHit(v.e,s.damage*3,s.build);playSignatureAudio(117,true,v.e.x,v.e.y);if(!doomLineValid(s)){s.finished=true;return false;}}}
 if(s.entries.every(v=>v.done&&(!v.impact||s.time-v.impact.time>=.3-1e-8))){s.finished=true;return false;}return true;};
const doomLinePaintBase=paintSignatureSpells;
paintSignatureSpells=()=>{doomLinePaintBase();const list=signatureRenderList(117);if(!list.length)return;for(const s of list){if(!doomLineValid(s))continue;const color=ELEMENTS[s.build.elements[0]].color;if(s.time<.3){const end={x:s.origin.x+Math.cos(s.angle)*s.length,y:s.origin.y+Math.sin(s.angle)*s.length};paintLinkLine(s.origin,end,color,3);}for(const v of s.entries){if(v.impact&&s.time-v.impact.time<.3){const q=v.impact;groundRing(q.x,q.y,25+70*(s.time-q.time),'#ffe4b8',3);paintLinkLine({x:q.x-24,y:q.y-24},{x:q.x+24,y:q.y+24},color,5);paintLinkLine({x:q.x+24,y:q.y-24},{x:q.x-24,y:q.y+24},color,5);}else if(doomLineEntryValid(v)){groundRing(v.e.x,v.e.y,30,color,2);boundarySigil(v.e,24,'#ffe4b8',s.time,3);}}}};
const doomLineStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===117?{label:'予告 '+s.entries.filter(v=>!v.done).length+'体 · HP35%以下で追撃',value:Math.max(0,1-s.time/5),waiting:true}:doomLineStatusBase(s);
